entries[5640] = { ["name"] = "Rezept: Wuttrank", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Wuttranks.\nBenötigt Klassische Alchemie\n(60)\nVerkaufspreis:\nWuttrank\nKlassen: Krieger , Druide\nBenutzen: Erzeugt sofort 15 bis 45 Wut. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Scharfe Klaue (2), Kristallphiole" }
entries[5642] = { ["name"] = "Rezept: Trank der freien Aktion", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Tranks der freien Aktion.\nBenötigt Klassische Alchemie\n(150)\nVerkaufspreis:\nTrank der freien Aktion\nBenutzen: Macht Euch [(50 - 50) * 30 ; Min 5, Max 30]) Sek. lang immun gegen Betäubungseffekte und bewegungseinschränkende Effekte. Bereits bestehende Effekte dieser Art werden nicht entfernt. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Schwarzmaulöl (2), Würgetang , Kristallphiole" }
