entries[6044] = { ["name"] = "Pläne: Eisenschildstachel", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Eisenschildstachels.\nBenötigt Klassische Schmiedekunst (150)\nVerkaufspreis:\nEisenschildstachel\nBenutzen: Bringt einen Eisenstachel an Eurem Schild an, der damit bei jedem Blocken Schaden verursacht. Kann nicht auf Gegenstände über Stufe 0 angewandt werden.\nVerkaufspreis:\nBenötigt Eisenbarren (6), Grober Schleifstein (4)" }
entries[6045] = { ["name"] = "Pläne: Eisengegengewicht", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Eisengegengewichts zum Ausbalancieren einer Zweihandwaffe.\nBenötigt Klassische Schmiedekunst (165)\nVerkaufspreis:\nEisengegengewicht\nBenutzen: Befestigt ein Gegengewicht an Zweihandschwertern, -streitkolben, -äxten oder -stangenwaffen und erhöht das Tempo des Trägers um 9. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Eisenbarren (4), Grober Schleifstein (2), Geringer Mondstein" }
entries[6046] = { ["name"] = "Pläne: Stahlwaffenkette", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Stahlwaffenkette.\nBenötigt Klassische Schmiedekunst (190)\nVerkaufspreis:\nStahlwaffenkette\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert. Ist nicht mit ähnlichen Effekten stapelbar. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Stahlbarren (8), Schwerer Schleifstein (2), Schweres Leder (4)" }
entries[6047] = { ["name"] = "Pläne: Goldene Schuppenhelmkappe", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer goldenen Schuppenhelmkappe.\nBenötigt Klassische Schmiedekunst (190)\nVerkaufspreis:\nGoldschuppenhelmkappe\nWird beim Anlegen gebunden\nKopf Kette\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nHaltbarkeit 70 / 70\nVerkaufspreis:\nBenötigt Stahlbarren (8), Goldbarren (2), Schwerer Schleifstein (2)\nOptionale Reagenzien: [] (#48)" }
